type Channel = "EMAIL" | "SMS" | "ADMIN_EMAIL";
type ChannelState = "sent" | "skipped" | "not_configured" | "failed";
type Lang = "tr" | "en" | "de" | "fr" | "es" | "ru" | "zh" | "ar" | "ku";
type Audience = "CUSTOMER" | "ADMIN";
type NoticeMedium = "email" | "sms";

