function formatDate(value:string|null,lang:Lang):string{if(!value)return"-";const date=new Date(value);if(Number.isNaN(date.getTime()))return value;const tag=lang==="tr"?"tr-TR":lang==="zh"?"zh-CN":lang==="ku"?"tr-TR":lang;try{return new Intl.DateTimeFormat(tag,{dateStyle:"medium",timeStyle:"short",timeZone:"Europe/Istanbul"}).format(date);}catch{return new Intl.DateTimeFormat("en",{dateStyle:"medium",timeStyle:"short",timeZone:"Europe/Istanbul"}).format(date);}}
