async function buildMail(booking:BookingRow,event:EventName,config:Record<string,any>,admin:boolean,context:NotificationContext){
  const lang=admin?"tr":language(booking.customer_locale);const l=labels(lang);const settings=config.site_settings||{};const profile=config.business_profile||{};
  const vars=notificationVars(booking,lang,context);const total=moneyValue(booking.total_price);const paid=moneyValue(booking.amount_paid);const balance=Math.max(0,Math.round((total-paid)*100)/100);
  const template=admin?null:await templateFor(event,"CUSTOMER",lang);
  const subject=admin?`${event==="payment_received"?"Ödeme alındı":"Yeni işlem"} | ${typeLabel(booking.booking_type,"tr")} | ${booking.reference}`:template?renderTemplate(template.subject_template,vars,240):`${subjectCopy[lang][event]} | ${booking.reference}`;
  const introText=admin?`${booking.customer_name} adlı müşteri için ${typeLabel(booking.booking_type,"tr").toLowerCase()} kaydında ${event==="payment_received"?"ödeme alındı":"yeni bir güncelleme var"}.`:template?renderTemplate(template.intro_template,vars,3000):`${l.hello} ${booking.customer_name}, talebiniz ${booking.reference} referansıyla sistemimize kaydedildi.`;
  const nextText=template?renderTemplate(template.next_step_template,vars,3000):nextStep(event,lang);
  const logoUrl=clean(settings.logoUrl,1000);const logo=/^https:\/\//i.test(logoUrl)?`<img src="${escapeHtml(logoUrl)}" alt="Alperler Auto" style="max-height:58px;max-width:220px;margin-bottom:20px" />`:`<div style="font-family:Georgia,serif;font-size:26px;font-weight:800;margin-bottom:20px">Alperler Auto</div>`;
  const phone=clean(settings.phone||profile.phone,80);const email=clean(settings.email||profile.email,180);const address=clean(settings.address||profile.address,300);const website=clean(profile.website,400);
  const social=[['Instagram',settings.instagramUrl],['Facebook',settings.facebookUrl],['TikTok',settings.tiktokUrl],['YouTube',settings.youtubeUrl],['X',settings.twitterUrl]].filter(([,url])=>typeof url==="string"&&/^https:\/\//i.test(String(url))).map(([name,url])=>`<a href="${escapeHtml(url)}" style="display:inline-block;margin:0 12px 8px 0;color:#bfdbfe;text-decoration:none;font-weight:700">${escapeHtml(name)}</a>`).join("");
  const rows=[[l.reference,booking.reference],[l.service,booking.item_name],[l.start,formatDate(booking.start_at,lang)],[l.end,formatDate(booking.end_at,lang)],[l.total,formatMoney(total,booking.currency,lang)],[l.paymentMethod,paymentMethodLabel(context.paymentMethod||booking.payment_method,lang)],[l.payment,paymentStatusLabel(booking.payment_status,lang)],[l.paid,formatMoney(paid,booking.currency,lang)],[l.balance,formatMoney(balance,booking.currency,lang)],[l.status,bookingStatusLabel(booking.status,lang)]];
  const notice=paymentNotice(booking,event,lang,context,"email");const noticeHtml=notice?`<div style="margin-top:18px;padding:16px;border-radius:14px;background:#fff7ed;border:1px solid #fed7aa;color:#9a3412;font-size:14px;line-height:1.65"><strong>${escapeHtml(paymentMethodLabel(context.paymentMethod||booking.payment_method,lang))}</strong><br>${escapeHtml(notice)}</div>`:"";
  const adminDetails=admin?`<div style="margin-top:18px;padding:14px 16px;border-radius:12px;background:#fff7ed;color:#9a3412;font-size:13px;line-height:1.6"><strong>Müşteri iletişimi</strong><br>${escapeHtml(booking.customer_phone)}${booking.customer_email?` · ${escapeHtml(booking.customer_email)}`:""}</div>`:"";
  const contact=[phone,email,address,website].filter(Boolean).map(escapeHtml).join(" · ");
  const html=`<!doctype html><html><body style="margin:0;background:#f1f5f9;font-family:Arial,Helvetica,sans-serif;color:#0f172a"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="padding:28px 12px"><tr><td align="center"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:680px;background:#fff;border:1px solid #dbe3ee;border-radius:20px;overflow:hidden;box-shadow:0 10px 30px rgba(15,23,42,.06)"><tr><td style="padding:32px">${logo}<div style="font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#2563eb">${escapeHtml(typeLabel(booking.booking_type,lang))}</div><h1 style="font-size:28px;line-height:1.2;margin:10px 0 14px">${escapeHtml(subject)}</h1><p style="font-size:16px;line-height:1.7;color:#475569;margin:0 0 22px">${escapeHtml(introText)}</p><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f8fafc;border-radius:14px">${rows.map(([label,value])=>`<tr><td style="padding:10px 16px;color:#64748b;font-size:13px;border-bottom:1px solid #edf2f7">${escapeHtml(label)}</td><td style="padding:10px 16px;text-align:right;font-weight:700;font-size:14px;border-bottom:1px solid #edf2f7">${escapeHtml(value)}</td></tr>`).join("")}</table>${noticeHtml}<div style="margin-top:20px;padding:18px;border-radius:14px;background:#eff6ff;border:1px solid #bfdbfe"><div style="font-size:12px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;color:#1d4ed8">${escapeHtml(l.next)}</div><p style="margin:8px 0 0;color:#1e3a8a;font-size:14px;line-height:1.65">${escapeHtml(nextText)}</p></div>${adminDetails}</td></tr><tr><td style="background:#071124;color:#cbd5e1;padding:24px 32px;font-size:12px;line-height:1.75"><strong style="color:#fff;font-size:14px">Alperler Auto</strong>${contact?`<br>${contact}`:""}${social?`<div style="margin-top:12px">${social}</div>`:""}</td></tr></table></td></tr></table></body></html>`;
  const plain=`${subject}\n\n${introText}\n\n${rows.map(([label,value])=>`${label}: ${value}`).join("\n")}${notice?`\n\n${notice}`:""}\n\n${l.next}: ${nextText}\n\nAlperler Auto${phone?` | ${phone}`:""}${email?` | ${email}`:""}`;
  return{subject,html,text:plain};
}

function normalizePhone(value:string):string|null{let phone=value.trim().replace(/[^0-9+]/g,"");if(phone.startsWith("00"))phone=`+${phone.slice(2)}`;if(/^05\d{9}$/.test(phone))phone=`+9${phone}`;else if(/^5\d{9}$/.test(phone))phone=`+90${phone}`;else if(/^90\d{10}$/.test(phone))phone=`+${phone}`;return/^\+[1-9]\d{7,14}$/.test(phone)?phone:null;}
async function acquire(bookingId:string,eventKey:string,channel:Channel,recipient:string):Promise<DeliveryLease>{const query=`notification_deliveries?booking_id=eq.${encodeURIComponent(bookingId)}&event_key=eq.${encodeURIComponent(eventKey)}&channel=eq.${channel}&select=id,status,provider_message_id,attempt_count&limit=1`;let response=await db(query);if(!response.ok)throw new Error("DELIVERY_STATE_READ_FAILED");let rows=await response.json();const existing=Array.isArray(rows)?rows[0]:null;if(existing&&["SENT","DELIVERED","PROCESSING"].includes(String(existing.status)))return{acquired:false,priorMessageId:existing.provider_message_id||undefined};if(existing?.id){response=await db(`notification_deliveries?id=eq.${encodeURIComponent(existing.id)}`,{method:"PATCH",headers:{Prefer:"return=minimal"},body:JSON.stringify({status:"PROCESSING",attempt_count:Number(existing.attempt_count||0)+1,last_error:null})});if(!response.ok)throw new Error("DELIVERY_LEASE_UPDATE_FAILED");return{acquired:true,id:existing.id};}response=await db("notification_deliveries?select=id",{method:"POST",headers:{Prefer:"return=representation"},body:JSON.stringify({booking_id:bookingId,event_key:eventKey,channel,recipient,status:"PROCESSING",attempt_count:1})});if(response.status===409)return{acquired:false};if(!response.ok)throw new Error("DELIVERY_LEASE_CREATE_FAILED");rows=await response.json();return{acquired:true,id:rows?.[0]?.id};}
async function finish(id:string|undefined,state:ChannelState,provider:string,messageId?:string,reason?:string):Promise<void>{if(!id)return;const status=state==="sent"?"SENT":state==="failed"?"FAILED":"SKIPPED";await db(`notification_deliveries?id=eq.${encodeURIComponent(id)}`,{method:"PATCH",headers:{Prefer:"return=minimal"},body:JSON.stringify({status,provider,provider_message_id:messageId||null,last_error:reason||null,sent_at:state==="sent"?new Date().toISOString():null})});}

async function emailChannel(to:string|null,booking:BookingRow,event:EventName,deliveryKey:string,config:Record<string,any>,admin:boolean,context:NotificationContext,credentials:ResendCredentials):Promise<ChannelReport>{
  if(!to)return{state:"skipped",reason:"EMAIL_MISSING"};const channel:Channel=admin?"ADMIN_EMAIL":"EMAIL";const lease=await acquire(booking.id,deliveryKey,channel,to);if(!lease.acquired)return{state:"sent",providerMessageId:lease.priorMessageId};
  if(!credentials.configured){await finish(lease.id,"not_configured","resend",undefined,"EMAIL_NOT_CONFIGURED");return{state:"not_configured",reason:"EMAIL_NOT_CONFIGURED"};}
  try{const mail=await buildMail(booking,event,config,admin,context);const response=await fetch("https://api.resend.com/emails",{method:"POST",headers:{authorization:`Bearer ${credentials.apiKey}`,"content-type":"application/json"},body:JSON.stringify({from:credentials.mailFrom,to:[to],subject:mail.subject,html:mail.html,text:mail.text}),signal:AbortSignal.timeout(10_000)});const result=await response.json().catch(()=>({}));if(!response.ok||!result.id)throw new Error(`EMAIL_SEND_FAILED_${response.status}`);await finish(lease.id,"sent","resend",String(result.id));return{state:"sent",providerMessageId:String(result.id)};}catch(error){const reason=error instanceof Error?error.message:"EMAIL_SEND_FAILED";await finish(lease.id,"failed","resend",undefined,reason);return{state:"failed",reason};}
}
async function smsChannel(booking:BookingRow,event:EventName,deliveryKey:string,context:NotificationContext,credentials:TwilioCredentials):Promise<ChannelReport>{
  const to=normalizePhone(booking.customer_phone);if(!to)return{state:"skipped",reason:"PHONE_MISSING_OR_INVALID"};const lease=await acquire(booking.id,deliveryKey,"SMS",to);if(!lease.acquired)return{state:"sent",providerMessageId:lease.priorMessageId};
  if(!credentials.configured){await finish(lease.id,"not_configured","twilio",undefined,"SMS_NOT_CONFIGURED");return{state:"not_configured",reason:"SMS_NOT_CONFIGURED"};}
  const lang=language(booking.customer_locale);const vars=notificationVars(booking,lang,context);const template=await templateFor(event,"CUSTOMER",lang);const subject=template?renderTemplate(template.subject_template,vars,240):subjectCopy[lang][event];const intro=template?renderTemplate(template.intro_template,vars,1200):`${booking.item_name} | ${booking.reference}`;const next=template?renderTemplate(template.next_step_template,vars,1200):nextStep(event,lang);const notice=paymentNotice(booking,event,lang,context,"sms");const body=`${subject} | ${intro}${notice?` ${notice}`:""} ${next}`.replace(/\s+/g," ").trim().slice(0,420);
  try{const payload=new URLSearchParams({To:to,Body:body});if(credentials.messagingServiceSid)payload.set("MessagingServiceSid",credentials.messagingServiceSid);else payload.set("From",credentials.from);const response=await fetch(`https://api.twilio.com/2010-04-01/Accounts/${encodeURIComponent(credentials.accountSid)}/Messages.json`,{method:"POST",headers:{authorization:`Basic ${btoa(`${credentials.accountSid}:${credentials.authToken}`)}`,"content-type":"application/x-www-form-urlencoded"},body:payload,signal:AbortSignal.timeout(10_000)});const result=await response.json().catch(()=>({}));if(!response.ok||!result.sid)throw new Error(`SMS_SEND_FAILED_${response.status}`);await finish(lease.id,"sent","twilio",String(result.sid));return{state:"sent",providerMessageId:String(result.sid)};}catch(error){const reason=error instanceof Error?error.message:"SMS_SEND_FAILED";await finish(lease.id,"failed","twilio",undefined,reason);return{state:"failed",reason};}
}

Deno.serve(async(request)=>{
  if(request.method!=="POST")return json({ok:false,code:"METHOD_NOT_ALLOWED"},405);if(!URL||!SERVICE_KEY)return json({ok:false,code:"SERVER_CONFIG_MISSING"},503);if(request.headers.get("authorization")!==`Bearer ${SERVICE_KEY}`)return json({ok:false,code:"FORBIDDEN"},403);
  let input:any;try{input=await request.json();}catch{return json({ok:false,code:"INVALID_JSON"},400);}const bookingId=clean(input?.bookingId,80);const event=clean(input?.event,40) as EventName;if(!bookingId||!EVENTS.includes(event))return json({ok:false,code:"INVALID_NOTIFICATION_REQUEST"},400);
  const suppliedKey=clean(input?.deliveryKey,120);const deliveryKey=/^[a-z0-9:_-]{3,120}$/i.test(suppliedKey)?suppliedKey:event;const context:NotificationContext={};const method=clean(input?.paymentMethod,20).toUpperCase();if(["CARD","EFT","OFFICE","NONE"].includes(method))context.paymentMethod=method;const paymentAmount=moneyValue(input?.paymentAmount);if(paymentAmount>0)context.paymentAmount=paymentAmount;const paymentTransactionId=clean(input?.paymentTransactionId,80);if(paymentTransactionId)context.paymentTransactionId=paymentTransactionId;
  try{const booking=await bookingById(bookingId);if(!booking)return json({ok:false,code:"BOOKING_NOT_FOUND"},404);const[config,resend,twilio]=await Promise.all([siteConfig(),resolveResendCredentials(),resolveTwilioCredentials()]);const adminTo=resend.adminTo||clean(config.site_settings?.email,240)||clean(config.business_profile?.email,240)||null;const[email,sms,adminEmail]=await Promise.all([emailChannel(booking.customer_email,booking,event,deliveryKey,config,false,context,resend),smsChannel(booking,event,deliveryKey,context,twilio),emailChannel(adminTo,booking,event,deliveryKey,config,true,context,resend)]);return json({ok:email.state==="sent"||sms.state==="sent"||adminEmail.state==="sent",bookingId,event,deliveryKey,email,sms,adminEmail});}catch(error){console.error("booking-notify failed",error);return json({ok:false,code:"NOTIFICATION_WORKER_FAILED"},500);}
});
